update public.recipes set title_en = 'Tomato Rice Pilaf', instructions_en = 'INGREDIENTS:
- 80 g rice
- 1 ripe tomato
- 1 small onion
- 1 tbsp butter
- 1 tbsp tomato paste
- salt

METHOD:
