update public.recipes set title_en = 'Simple Chicken with Tomatoes', instructions_en = 'INGREDIENTS:
- 200 g chicken breast
- 2 ripe tomato
- 1 green pepper
- 5 ml olive oil
- salt and black pepper

METHOD:
